			version = 1,
			names = { ["area:426"] = "Raynewood Retreat", ["area:429"] = "Xavian", ["area:431"] = "Splintertree Post", ["item:7269"] = "Deino's Flask", ["npc:3484"] = "Kil'hala", ["npc:4568"] = "Anastasia Hartwell", ["npc:5885"] = "Deino", ["object:172961"] = "Valley of Spirits", ["object:173161"] = "Darkbriar Lodge", ["object:174797"] = "Xavian Waterfall", ["object:36082"] = "Magic Quarter", ["quest:1945"] = "Laughing Sisters", ["quest:1946"] = "Nether-lace Garment", ["spell:3563"] = "Teleport: Undercity", ["spell:3567"] = "Teleport: Orgrimmar", ["zone:1420"] = "Tirisfal Glades", ["zone:1440"] = "Ashenvale", ["zone:1454"] = "Orgrimmar", ["zone:1458"] = "Undercity" },
			steps = {
				{
					title = "{npc:4568}",
					note = "{npc:4568} stands in the {zone:1458}'s {object:36082}. Orcs and Trolls use {spell:3563} or take the zeppelin from {zone:1454} to {zone:1420} for her.",
					goals = {
						{ t = "level", level = 26 },
						{ t = "accept", quest = 1943, title = "Speak with Deino", npc = 4568, npcName = "Anastasia Hartwell", minLevel = 26, qlvl = 26, closedBy = { 1944 }, preTitles = { [1944] = "Waters of Xavian" }, map = 1458, x = 85.14, y = 10.03, z = -47.3, f = "e" },
					},
				},
				{
					title = "{npc:5885}",
					note = "Take the zeppelin to {zone:1454} (or use {spell:3567}, which lands you on the upper floor of {object:173161}). {npc:5885} stands with the mage trainers on the lower floor of {object:173161} in the {object:172961}. She hands you {item:7269}.",
					goals = {
						{ t = "turnin", quest = 1943, title = "Speak with Deino", npc = 5885, npcName = "Deino", map = 1454, x = 38.45, y = 86.13, z = 43, f = "e" },
						{ t = "accept", quest = 1944, title = "Waters of Xavian", npc = 5885, npcName = "Deino", minLevel = 26, qlvl = 26, map = 1454, x = 38.45, y = 86.13, z = 43, f = "e" },
					},
				},
				{
					title = "The {object:174797}",
