						{ t = "accept", quest = 2458, title = "Deep Cover", npc = 3401, npcName = "Shenthul", minLevel = 20, qlvl = 20, pre = { 2460 }, preTitles = { [2460] = "The Shattered Salute" }, map = 1454, x = 43.05, y = 53.74, z = 7.8, f = "e", note = "{quest:2458}: keep the {item:8051}" },
					},
				},
				{
					title = "{npc:7233}",
					note = "Fly to the Crossroads and head north to the Venture Co. tower above the {area:382}. Fizzule stands under a tree east of the tower, outside it, and is hostile until signalled. Target him from about 50 yards and fire the {item:8051} twice, then walk up in front of him and /salute. In any other order he attacks. Lost the {item:8051}? Abandon and retake from {npc:3401}.",
					goals = {
						{ t = "use", item = 8051, itemName = "Flare Gun", map = 1413, x = 55.4, y = 5.6, f = "e", note = "{item:8051}, twice, at Fizzule" },
						{ t = "turnin", quest = 2458, title = "Deep Cover", npc = 7233, npcName = "Taskmaster Fizzule", map = 1413, x = 55.44, y = 5.56, z = 91.8, f = "e", note = "{npc:7233}: {item:8066}", rewards = { items = { { item = 8066, itemName = "Fizzule's Whistle" } } } },
						{ t = "accept", quest = 2478, title = "Mission: Possible But Not Probable", npc = 7233, npcName = "Taskmaster Fizzule", minLevel = 20, qlvl = 24, pre = { 2458 }, preTitles = { [2458] = "Deep Cover" }, map = 1413, x = 55.44, y = 5.56, z = 91.8, f = "e" },
					},
				},
				{
					title = "{item:8072}",
					note = "Keep {item:8066} in your bags and use it on him every time you come near, or he turns hostile. {npc:7287} (level 22) walks by the tower: hug the wall, stealth up behind him and {spell:921} the key. Killing him does not give it; if his pockets are empty, kill him and wait 4 1/2 minutes for him to come back.",
					goals = {
						{ t = "collect", quest = 2478, title = "Mission: Possible But Not Probable", item = 8072, itemName = "Silixiz's Tower Key", count = 1, oi = 5, text = "Pick Pocket Foreman Silixiz for {item:8072}", map = 1413, x = 54.8, y = 5.97, f = "e", from = "Foreman Silixiz", fromKind = "npc", fromId = 7287, fromNpcs = { { npc = 7287, npcName = "Foreman Silixiz" } } },
					},
				},
				{
					title = "The Venture Co. tower",
					note = "Inside, floor by floor (everything comes back after 4 1/2 minutes): the Mutated Venture Co. Drones (level 25) on the ground floor die to one Ambush with a dagger; the Patrollers on the second floor take half their health from a one-point {spell:1943}; the Lookouts on the open third floor from a one-point {spell:2098}. {npc:7288} waits on the top floor: a level 23 elite, back 10 minutes after a kill. Open with Ambush (about half his health), then {spell:1776}, {spell:5277}, a healing potion and {item:7676}; a friend makes it easy. One head per kill. Then pick {object:129127} beside him for the cache: it poisons you with the {spell:9810}, which weakens your stealth and agility until {npc:2391} cures it.",
					goals = {
						{ t = "kill", quest = 2478, title = "Mission: Possible But Not Probable", target = "Mutated Venture Co. Drone", npc = 7310, count = 2, oi = 1, map = 1413, x = 54.7, y = 5.7, z = 93.3, f = "e" },
						{ t = "kill", quest = 2478, title = "Mission: Possible But Not Probable", target = "Venture Co. Patroller", npc = 7308, count = 2, oi = 3, map = 1413, x = 54.66, y = 5.68, z = 107.1, f = "e" },
						{ t = "kill", quest = 2478, title = "Mission: Possible But Not Probable", target = "Venture Co. Lookout", npc = 7307, count = 2, oi = 2, map = 1413, x = 54.64, y = 5.77, z = 120.7, f = "e" },
						{ t = "collect", quest = 2478, title = "Mission: Possible But Not Probable", item = 8074, itemName = "Gallywix's Head", count = 1, oi = 4, map = 1413, x = 54.75, y = 5.59, f = "e", note = "{item:8074}: {npc:7288} (elite)", from = "Grand Foreman Puzik Gallywix", fromKind = "npc", fromRank = 1, fromId = 7288, fromNpcs = { { npc = 7288, npcName = "Grand Foreman Puzik Gallywix" } }, group = { kind = "elite", lvl = 23, rank = 1 } },
						{ t = "collect", quest = 2478, title = "Mission: Possible But Not Probable", item = 8073, itemName = "Cache of Zanzil's Altered Mixture", count = 1, oi = 6, map = 1413, x = 54.76, y = 5.56, f = "e", note = "{item:8073}: {object:129127}", from = "Gallywix's Lockbox", fromKind = "object", fromId = 129127 },
					},
				},
				{
					title = "Back to {npc:3401}",
					note = "Fly back to {zone:1454} ({area:392} or the Crossroads; dying at the tower and taking the spirit healer's way back to the Crossroads is quicker). Keep {item:8072} afterwards. Before you leave the {area:263}, buy {item:2928} and Empty Vials from Rekkul: once Hinott teaches Poisons, each batch of {spell:8681} takes one of each.",
					goals = {
						{ t = "turnin", quest = 2478, title = "Mission: Possible But Not Probable", npc = 3401, npcName = "Shenthul", map = 1454, x = 43.05, y = 53.74, z = 7.8, f = "e", note = "{npc:3401}: {item:18160}", rewards = { items = { { item = 18160, itemName = "Recipe: Thistle Tea" } } } },
						{ t = "accept", quest = 2479, title = "Hinott's Assistance", npc = 3401, npcName = "Shenthul", minLevel = 20, qlvl = 26, pre = { 2478 }, preTitles = { [2478] = "Mission: Possible But Not Probable" }, map = 1454, x = 43.05, y = 53.74, z = 7.8, f = "e" },
					},
				},
				{
					title = "{npc:2391}",
					note = "Take the zeppelin from {zone:1454} to the {zone:1458} and follow the road south through {zone:1421} into {area:287}, to {area:272}. {npc:2391} works in the building next to the flight path, beside {npc:2216}, a wagon outside. If you lost the Sample of Zanzil's Mixture, abandon and retake from {npc:3401}. Stay beside him for about a minute while he brews the cure; if it never finishes, abandon and retake from him. Then open Poisons from your spellbook to make {spell:8681} from Rekkul's dust and vials, and use it on your weapon.",
					goals = {
						{ t = "getfp", npc = 2389, npcName = "Zarise", location = "Tarren Mill", node = 13, area = 272, map = 1424, x = 60.14, y = 18.62, z = 58.9, f = "e", optional = true },
						{ t = "turnin", quest = 2479, title = "Hinott's Assistance", npc = 2391, npcName = "Serge Hinott", map = 1424, x = 61.63, y = 19.19, z = 57.6, f = "e" },
						{ t = "accept", quest = 2480, title = "Hinott's Assistance", npc = 2391, npcName = "Serge Hinott", minLevel = 20, qlvl = 20, pre = { 2479 }, preTitles = { [2479] = "Hinott's Assistance" }, map = 1424, x = 61.63, y = 19.19, z = 57.6, f = "e" },
						{ t = "complete", quest = 2480, title = "Hinott's Assistance", note = "Wait for the cure", objs = { { text = "Cure Completed", count = 1 } } },
						{ t = "turnin", quest = 2480, title = "Hinott's Assistance", npc = 2391, npcName = "Serge Hinott", map = 1424, x = 61.63, y = 19.19, z = 57.6, f = "e", note = "{npc:2391}: Poisons", rewards = { items = { { item = 8095, itemName = "Hinott's Oil" } } } },
						{ t = "use", item = 8095, itemName = "Hinott's Oil", map = 1424, x = 61.63, y = 19.19, f = "e", optional = true, note = "{item:8095}: clears the {spell:9810}" },
					},
