			},
		})
	end
	register()
end

-- Source: forever/class/shaman/call-of-air-horde.guide
do
	local function register()
		Polestar.RegisterGuide({
			id = "forever/class/shaman/call-of-air-horde",
			pack = "guides",
			title = "{quest:1531} and the Tempest's Weapons (Horde)",
			faction = "Horde",
			classes = { "SHAMAN" },
			minLevel = 30,
			maxLevel = 40,
			category = "Class",
			folder = "Shaman",
			keywords = { "Air Totem", "Elemental Aid", "Eyes on the Sky", "Storm", "Earth", "and Fire", "Heed My Call", "The Tempest's Weapons", "Prate Cloudseer", "Rau Cliffrunner", "Bath'rah the Windwatcher", "Alaana Stormwalker", "Razorfen Kraul", "Charlga Razorflank", "Twisted Totem", "Corrupted Totems", "Ravaging Tempest", "Eye of the Tempest", "Lightning's Grasp", "Tidebringer's Claw", "Rage of the Storm", "Elementalist's Guard", "Skyborne", "Shaman", "class quest", "totem", "weapon" },
			reward = { { item = 5178, itemName = "Air Totem" }, { item = 280607, itemName = "Lightning's Grasp", choice = true }, { item = 280605, itemName = "Tidebringer's Claw", choice = true }, { item = 280604, itemName = "Rage of the Storm", choice = true }, { item = 280696, itemName = "Elementalist's Guard" } },
			why = "The {item:5178} that lets you place air totems, then a weapon of your choice at 40.",
			zone = 1454,
			zoneName = "Orgrimmar",
			author = "Polestar",
			version = 1,
			group = true,
			names = { ["area:1640"] = "Spirit Rise", ["area:1717"] = "Razorfen Kraul", ["area:2408"] = "Shadowprey Village", ["area:272"] = "Tarren Mill", ["area:338"] = "Angor Fortress", ["area:484"] = "Freewind Post", ["area:496"] = "Brackenwall Village", ["area:75"] = "Stonard", ["item:212792"] = "Eye of the Tempest", ["item:268582"] = "Corrupted Totems", ["item:274044"] = "Twisted Fire Totem", ["item:274045"] = "Twisted Earth Totem", ["item:274046"] = "Twisted Water Totem", ["item:274047"] = "Twisted Air Totem", ["item:274463"] = "Tattered Note", ["item:280604"] = "Rage of the Storm", ["item:280605"] = "Tidebringer's Claw", ["item:280607"] = "Lightning's Grasp", ["item:280696"] = "Elementalist's Guard", ["item:5178"] = "Air Totem", ["npc:216474"] = "Ravaging Tempest", ["npc:256028"] = "The Lost One", ["npc:259119"] = "Alaana Stormwalker", ["npc:3560"] = "Healing Ward", ["npc:4421"] = "Charlga Razorflank", ["npc:4722"] = "Rau Cliffrunner", ["npc:5879"] = "Fire Nova Totem", ["npc:5892"] = "Searn Firewarder", ["npc:5905"] = "Prate Cloudseer", ["npc:5906"] = "Xanis Flameweaver", ["npc:6176"] = "Bath'rah the Windwatcher", ["object:172957"] = "Valley of Wisdom", ["quest:1531"] = "Call of Air", ["quest:96136"] = "Call of Air", ["spell:10596"] = "Nature Resistance", ["spell:139"] = "Renew", ["spell:8292"] = "Chain Bolt", ["spell:9654"] = "Jumping Lightning", ["zone:1412"] = "Mulgore", ["zone:1413"] = "Barrens", ["zone:1416"] = "Alterac Mountains", ["zone:1418"] = "Badlands", ["zone:1435"] = "Swamp of Sorrows", ["zone:1441"] = "Thousand Needles", ["zone:1443"] = "Desolace", ["zone:1445"] = "Dustwallow Marsh", ["zone:1454"] = "Orgrimmar", ["zone:1456"] = "Thunder Bluff" },
			written = { ["At 30 {npc:5906}, a shaman trainer on {area:1640} in {zone:1456}, sends you to {npc:5905} in {zone:1441}. Your level 30 air totems (Grounding, {spell:10596}) need the Air Totem Prate gives. Already carry {npc:5892}'s {quest:1531} from {zone:1454}? It goes to {npc:5905} too: skip {npc:5906}."] = "At 30 Xanis Flameweaver, a shaman trainer on Spirit Rise in Thunder Bluff, sends you to Prate Cloudseer in Thousand Needles. Your level 30 air totems (Grounding, Nature Resistance) need the Air Totem Prate gives. Already carry Searn Firewarder's Call of Air from Orgrimmar? It goes to Prate too: skip Xanis.", ["{npc:5905} hands you the {item:268582}. Place the {item:268582} at the steam pools north-west of {area:484} to call the corrupted elementals and then the {npc:216474}; Razormane quilboar join the fight while the ritual runs. A group quest: bring at least one or two friends. The {item:212792} drops about every other kill, and every group member can loot it."] = "Prate hands you the Corrupted Totems. Place the Corrupted Totems at the steam pools north-west of Freewind Post to call the corrupted elementals and then the Ravaging Tempest; Razormane quilboar join the fight while the ritual runs. A group quest: bring at least one or two friends. The Eye of the Tempest drops about every other kill, and every group member can loot it.", ["{npc:6176} camps in the ruins in the east of {zone:1416}: from {area:272} follow the river east of town north into the hills. Pick your weapon: {item:280607}, {item:280605} or {item:280604}; the {item:280696} shield comes with it."] = "Bath'rah camps in the ruins in the east of Alterac Mountains: from Tarren Mill follow the river east of town north into the hills. Pick your weapon: Lightning's Grasp, Tidebringer's Claw or Rage of the Storm; the Elementalist's Guard shield comes with it." },
			steps = {
