						{ t = "accept", quest = 96, title = "Call of Water", npc = 5895, npcName = "Minor Manifestation of Water", minLevel = 20, qlvl = 23, pre = { 100 }, preTitles = { [100] = "Call of Water" }, map = 1421, x = 38.65, y = 44.58, f = "e" },
