						{ t = "accept", quest = 1801, title = "Tome of the Cabal", npc = 6251, npcName = "Strahad Farsan", minLevel = 30, qlvl = 30, map = 1413, x = 62.63, y = 35.5, z = 40.5, f = "e" },
