				{
					title = "{item:6997}",
					note = "The centaur cave opens in the cliffs north of {area:484}. Inside, keep right at each fork, cross the pool by the small waterfall, and open the small dark box against the wall beside a larger chest: the larger one is the wrong one. You can open it only while on the quest. The centaurs respawn behind you on the way out.",
					goals = {
						{ t = "collect", quest = 1803, title = "Tome of the Cabal", item = 6997, itemName = "Tattered Manuscript", count = 1, oi = 2, map = 1441, x = 43.44, y = 32.69, f = "e", note = "{item:6997}, in the {object:92423}", from = "Damaged Chest", fromKind = "object", fromId = 92423 },
					},
				},
				{
					title = "Back to {npc:6293}",
					note = "{npc:6293} pieces the tome together and gives you the {item:7006}: keep it, {npc:6251} takes it with the rods.",
					goals = {
