						{ t = "accept", quest = 1805, title = "Tome of the Cabal", npc = 6293, npcName = "Jorah Annison", minLevel = 30, qlvl = 30, pre = { 1803 }, preTitles = { [1803] = "Tome of the Cabal" }, map = 1458, x = 75.92, y = 37.89, z = -62.1, f = "e" },
					},
				},
				{
					title = "Rods of Channeling",
					note = "The Dragonmaw hold {area:1036} in the hills east of the road through the {zone:1437}, south of the {area:881} you cross from {zone:1417}. Only the casters drop the rods, four kills in five: the Bonewarders (level 27, with skeleton pets) and Shadowwarders (28). A steep path north of the central spirit healer leads up into the camp past most of the warriors.",
					goals = {
						{ t = "collect", quest = 1805, title = "Tome of the Cabal", item = 6930, itemName = "Rod of Channeling", count = 3, oi = 1, map = 1437, x = 52.38, y = 52.64, f = "e", spotsPacked = "53.1,54.2,,32,4,,29;50.6,50.9,,34,3;51.7,49,,18,2;49,46.7,,59,10,,29;46.1,46.4,,38,4;45.6,42.9,,15,2", lvl = 27, note = "Rods of Channeling, from the Dragonmaw casters", from = "Dragonmaw Shadowwarder", fromKind = "npc", fromAlso = "Dragonmaw Bonewarder", fromId = 1038, fromAlsoId = 1057, fromNpcs = { { npc = 1038, npcName = "Dragonmaw Shadowwarder" }, { npc = 1057, npcName = "Dragonmaw Bonewarder" } } },
					},
				},
				{
					title = "{quest:1795}",
					note = "Back to {npc:6251} in {area:392}. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the {quest:1804} on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon {quest:1795} and take it again from {npc:6251}. Keep the tome: {npc:6251} takes it back.",
					goals = {
