			reward = { { spell = 712, spellName = "Summon Succubus" }, { spell = 713, spellName = "Summon Incubus" }, { item = 22243, itemName = "Small Soul Pouch" } },
			why = "At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards.",
			zone = 1454,
			zoneName = "Orgrimmar",
			author = "Polestar",
			version = 1,
			names = { ["area:230"] = "Greymane Wall", ["area:233"] = "Ambermill", ["area:2539"] = "Malaka'jin", ["area:279"] = "Dalaran", ["area:287"] = "Hillsbrad", ["area:378"] = "Camp Taurajo", ["area:392"] = "Ratchet", ["area:422"] = "Fallen Sky Lake", ["area:431"] = "Splintertree Post", ["area:881"] = "Thandol Span", ["item:190181"] = "Lovers' Hearts", ["item:190232"] = "Withered Scarf", ["item:6286"] = "Pure Hearts", ["item:6626"] = "Dogran's Pendant", ["npc:185333"] = "Avelina Lilly", ["npc:185334"] = "Isaac Pearson", ["npc:185335"] = "Summoned Incubus", ["npc:3216"] = "Neeru Fireblade", ["npc:3363"] = "Magar", ["npc:3464"] = "Gazrog", ["npc:3782"] = "Shadethicket Stone Mover", ["npc:3931"] = "Shadethicket Oracle", ["npc:4197"] = "Ken'zigla", ["npc:5675"] = "Carendin Halgar", ["npc:5682"] = "Dalin Forgewright", ["npc:5683"] = "Corma Villard", ["npc:5693"] = "Godrick Farsan", ["npc:5875"] = "Gan'rul Bloodeye", ["npc:5908"] = "Grunt Dogran", ["npc:5909"] = "Cazul", ["npc:5910"] = "Zankaja", ["npc:5911"] = "Grunt Logmar", ["object:1661"] = "The Undercity", ["object:172960"] = "Cleft of Shadow", ["object:172982"] = "Valley of Strength", ["object:173018"] = "Magar's Cloth Goods", ["object:36082"] = "Magic Quarter", ["quest:1472"] = "Devourer of Souls", ["quest:1474"] = "The Binding", ["quest:1513"] = "The Binding", ["quest:65597"] = "The Binding", ["quest:65604"] = "The Binding", ["spell:712"] = "Summon Succubus", ["spell:713"] = "Summon Incubus", ["zone:1411"] = "Durotar", ["zone:1413"] = "Barrens", ["zone:1417"] = "Arathi Highlands", ["zone:1437"] = "Wetlands", ["zone:1440"] = "Ashenvale", ["zone:1442"] = "Stonetalon Mountains", ["zone:1454"] = "Orgrimmar", ["zone:1458"] = "Undercity" },
			written = { ["At 20 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:5909} a few steps away. Two trainers start these demons, {npc:5875} here and {npc:5675} in the {zone:1458}, and you can take only one; this guide follows whichever {quest:1472} you took. {npc:5909} offers both of {zone:1454}'s branches: take both."] = "At 20 Gan'rul Bloodeye, in the Cleft of Shadow under the Valley of Strength, sends you to Cazul a few steps away. Two trainers start these demons, Gan'rul here and Carendin Halgar in the Undercity, and you can take only one; this guide follows whichever Devourer of Souls you took. Cazul offers both of Orgrimmar's branches: take both.", ["Back to {npc:5675} with Dalin's and {npc:5683}'s hearts. He hands you the {item:6286}: go down to the summoning circle below him, stand on it and use them. Summon your voidwalker first and keep the fight on the circle, or the guards may kill her and the kill does not count. If she wins, use the hearts again; keep them, {npc:5675} takes them back."] = "Back to Carendin with Dalin's and Corma's hearts. He hands you the Pure Hearts: go down to the summoning circle below him, stand on it and use them. Summon your voidwalker first and keep the fight on the circle, or the guards may kill her and the kill does not count. If she wins, use the hearts again; keep them, Carendin takes them back.", ["Back to {npc:5675} with the lovers' hearts, then place the {item:190181} on the same circle and defeat the incubus they call (level 20, not elite; it can charm you). Keep the hearts: {npc:5675} takes them back."] = "Back to Carendin with the lovers' hearts, then place the Lovers' Hearts on the same circle and defeat the incubus they call (level 20, not elite; it can charm you). Keep the hearts: Carendin takes them back.", ["Back to {npc:5875} with the pendant. He hands you {item:6626}: take it across the {object:172960} to {npc:3216}'s tent, stand on the purple circle and use it. Summon your voidwalker first and let it tank: the succubus (level 20, not elite) charms and lashes; keep your damage over time on her. If she wins, use the pendant again. Keep the pendant: {npc:5875} takes it back."] = "Back to Gan'rul with the pendant. He hands you Dogran's Pendant: take it across the Cleft of Shadow to Neeru Fireblade's tent, stand on the purple circle and use it. Summon your voidwalker first and let it tank: the succubus (level 20, not elite) charms and lashes; keep your damage over time on her. If she wins, use the pendant again. Keep the pendant: Gan'rul takes it back.", ["Back to {npc:5875} with the scarf, then use the {item:190232} on the same circle in Neeru's tent and defeat the incubus it calls (level 20, not elite) with your voidwalker tanking. Keep the scarf: {npc:5875} takes it back."] = "Back to Gan'rul with the scarf, then use the Withered Scarf on the same circle in Neeru's tent and defeat the incubus it calls (level 20, not elite) with your voidwalker tanking. Keep the scarf: Gan'rul takes it back.", ["{item:6286}, on the circle below {npc:5675}"] = "Pure Hearts, on the circle below Carendin", ["{npc:185335}, at the circle below {npc:5675}"] = "Summoned Incubus, at the circle below Carendin", ["{npc:5911} stands at {area:378}, south down the road from the Crossroads. He sends you north to the quilboar camp where Dogran is held: the camp with two huts side by side, north-west of a decoy camp whose huts stand apart. A rare level 22 elite quilboar sometimes guards the huts: send your voidwalker in, sacrifice it if you must, and talk to Dogran. He gives you a pendant for {npc:5875}. Keep it."] = "Grunt Logmar stands at Camp Taurajo, south down the road from the Crossroads. He sends you north to the quilboar camp where Dogran is held: the camp with two huts side by side, north-west of a decoy camp whose huts stand apart. A rare level 22 elite quilboar sometimes guards the huts: send your voidwalker in, sacrifice it if you must, and talk to Dogran. He gives you a pendant for Gan'rul. Keep it.", ["{object:1661}'s version, for warlocks who took {npc:5675}'s {quest:1472} instead of {npc:5875}'s. At 20 {npc:5675}, in the {object:36082}, sends you to {npc:5693} close by. {npc:5693} shows you an image of each quarry and offers both branches: take both."] = "The Undercity's version, for warlocks who took Carendin Halgar's Devourer of Souls instead of Gan'rul's. At 20 Carendin, in the Magic Quarter, sends you to Godrick Farsan close by. Godrick shows you an image of each quarry and offers both branches: take both." },
			steps = {
