						{ t = "accept", quest = 65593, title = "Hearts of the Lovers", npc = 5693, npcName = "Godrick Farsan", minLevel = 20, qlvl = 20, pre = { 1472 }, closedBy = { 1507 }, preTitles = { [1472] = "Devourer of Souls", [1507] = "Devourer of Souls" }, map = 1458, x = 84.81, y = 14.83, z = -61.4, f = "e", note = "the incubus" },
					},
				},
				{
					title = "Silverpine hearts",
					note = "{npc:185333} (level 22) works as a tailor for the {area:279} wizards at {area:233}, in eastern Silverpine: the wizards around her are hostile. {npc:5682} (level 20, not elite) patrols near the {area:230} in the far south. Both are Alliance-friendly humans: attacking them can flag you for PvP. Each drops her or his heart.",
					goals = {
						{ t = "collect", quest = 65593, title = "Hearts of the Lovers", item = 190179, itemName = "Avelina's Heart", count = 1, oi = 1, map = 1421, x = 63.12, y = 65.27, f = "e", from = "Avelina Lilly", fromKind = "npc", fromId = 185333, fromNpcs = { { npc = 185333, npcName = "Avelina Lilly" } } },
						{ t = "collect", quest = 1476, title = "Hearts of the Pure", item = 6312, itemName = "Dalin's Heart", count = 1, oi = 1, map = 1421, x = 47.6, y = 85.65, f = "e", from = "Dalin Forgewright", fromKind = "npc", fromFaction = "A", fromId = 5682, fromNpcs = { { npc = 5682, npcName = "Dalin Forgewright" } } },
					},
				},
				{
					title = "{npc:5683}",
					note = "{npc:5683} (level 22, not elite; Comar in older records) wanders the north of the {zone:1437} just past the {area:881}, to the right as you come off the bridge. From the {zone:1458} head through {area:287} and {zone:1417}, where the mobs are 30 and up. Attacking her flags you for PvP.",
					goals = {
						{ t = "collect", quest = 1476, title = "Hearts of the Pure", item = 6313, itemName = "Corma's Heart", count = 1, oi = 2, map = 1437, x = 49.93, y = 12.55, f = "e", from = "Corma Villard", fromKind = "npc", fromFaction = "A", fromId = 5683, fromNpcs = { { npc = 5683, npcName = "Corma Villard" } } },
					},
				},
				{
					title = "{quest:1474}: succubus ({zone:1458})",
					note = "Back to {npc:5675} with Dalin's and {npc:5683}'s hearts. He hands you the {item:6286}: go down to the summoning circle below him, stand on it and use them. Summon your voidwalker first and keep the fight on the circle, or the guards may kill her and the kill does not count. If she wins, use the hearts again; keep them, {npc:5675} takes them back.",
					goals = {
						{ t = "turnin", quest = 1476, title = "Hearts of the Pure", npc = 5675, npcName = "Carendin Halgar", map = 1458, x = 85.06, y = 25.99, z = -62.2, f = "e" },
