						{ t = "use", item = 6286, itemName = "Pure Hearts", map = 1458, x = 86.6, y = 27.1, f = "e", note = "{item:6286}, on the circle below {npc:5675}" },
						{ t = "kill", quest = 1474, title = "The Binding", target = "Summoned Succubus", npc = 5677, count = 1, oi = 1, map = 1458, x = 86.7, y = 27.1, f = "e" },
						{ t = "turnin", quest = 1474, title = "The Binding", npc = 5675, npcName = "Carendin Halgar", map = 1458, x = 85.06, y = 25.99, z = -62.2, f = "e", note = "{npc:5675}: {spell:712}" },
					},
				},
				{
					title = "{npc:185334}",
					note = "{npc:185334} (level 22) works in {area:392}, on the {zone:1413} coast, at one of two spots in town: take the zeppelin to {zone:1411} and head south, or fly from {zone:1454}. He is an Alliance-friendly human: attacking him can flag you for PvP.",
					goals = {
						{ t = "collect", quest = 65593, title = "Hearts of the Lovers", item = 190180, itemName = "Isaac's Heart", count = 1, oi = 2, map = 1413, x = 62.13, y = 38.35, f = "e", spotsPacked = "62.1,38.3,,30,2", lvl = 22, from = "Isaac Pearson", fromKind = "npc", fromId = 185334, fromNpcs = { { npc = 185334, npcName = "Isaac Pearson" } } },
					},
				},
				{
					title = "{quest:65597}: incubus ({zone:1458})",
					note = "Back to {npc:5675} with the lovers' hearts, then place the {item:190181} on the same circle and defeat the incubus they call (level 20, not elite; it can charm you). Keep the hearts: {npc:5675} takes them back.",
					goals = {
						{ t = "turnin", quest = 65593, title = "Hearts of the Lovers", npc = 5675, npcName = "Carendin Halgar", map = 1458, x = 85.06, y = 25.99, z = -62.2, f = "e" },
						{ t = "accept", quest = 65597, title = "The Binding", npc = 5675, npcName = "Carendin Halgar", minLevel = 20, qlvl = 20, pre = { 65593 }, closedBy = { 1507 }, preTitles = { [1507] = "Devourer of Souls", [65593] = "Hearts of the Lovers" }, map = 1458, x = 85.06, y = 25.99, z = -62.2, f = "e" },
						{ t = "kill", quest = 65597, title = "The Binding", target = "Summoned Incubus", npc = 185335, count = 1, oi = 1, map = 1458, x = 84.98, y = 25.21, f = "e", spotsPacked = "85.7,26.8,,20,4", lvl = 20, note = "{npc:185335}, at the circle below {npc:5675}" },
						{ t = "turnin", quest = 65597, title = "The Binding", npc = 5675, npcName = "Carendin Halgar", map = 1458, x = 85.06, y = 25.99, z = -62.2, f = "e", note = "{npc:5675}: {spell:713}" },
