-- Source: forever/class/warlock/voidwalker-horde.guide
do
	local function register()
		Polestar.RegisterGuide({
			id = "forever/class/warlock/voidwalker-horde",
			pack = "guides",
			title = "Voidwalker (Horde)",
			faction = "Horde",
			classes = { "WARLOCK" },
			minLevel = 10,
			maxLevel = 12,
			category = "Class",
			folder = "Warlock",
			keywords = { "Summon Voidwalker", "Gan'rul's Summons", "Halgar's Summons", "Creature of the Void", "The Binding", "Ophek", "Gan'rul Bloodeye", "Ageron Kargal", "Carendin Halgar", "Tablet of Verga", "Burning Blade Stash", "Skull Rock", "Egalin's Grimoire", "Perrine's Chest", "Glyphs of Summoning", "Runes of Summoning", "Neeru Fireblade", "Summoning Circle", "Warlock", "class pet" },
			reward = { { spell = 697, spellName = "Summon Voidwalker" } },
			why = "Your tank demon at 10: the voidwalker, after a stolen book and a fight at a summoning circle.",
			zone = 1411,
			zoneName = "Durotar",
			author = "Polestar",
			version = 1,
			names = { ["area:154"] = "Deathknell", ["area:159"] = "Brill", ["area:2119"] = "Gallows' End Tavern", ["area:362"] = "Razor Hill", ["area:817"] = "Skull Rock", ["item:6284"] = "Runes of Summoning", ["item:6285"] = "Egalin's Grimoire", ["item:6535"] = "Tablet of Verga", ["item:7464"] = "Glyphs of Summoning", ["npc:1537"] = "Scarlet Zealot", ["npc:1662"] = "Captain Perrine", ["npc:3172"] = "Dhugru Gorelust", ["npc:3198"] = "Burning Blade Apprentice", ["npc:3204"] = "Gazz'uz", ["npc:3216"] = "Neeru Fireblade", ["npc:3294"] = "Ophek", ["npc:5675"] = "Carendin Halgar", ["npc:5724"] = "Ageron Kargal", ["npc:5875"] = "Gan'rul Bloodeye", ["object:172960"] = "Cleft of Shadow", ["object:172982"] = "Valley of Strength", ["object:36082"] = "Magic Quarter", ["object:37098"] = "Perrine's Chest", ["object:58595"] = "Burning Blade Stash", ["quest:1471"] = "The Binding", ["quest:1478"] = "Halgar's Summons", ["quest:1504"] = "The Binding", ["quest:1506"] = "Gan'rul's Summons", ["spell:14868"] = "Curse of Agony", ["spell:348"] = "Immolate", ["spell:697"] = "Summon Voidwalker", ["zone:1420"] = "Tirisfal Glades", ["zone:1454"] = "Orgrimmar", ["zone:1458"] = "Undercity" },
			written = { ["At 10 {npc:3294} sends you to {npc:5875}. He stands outside at the back of {area:362}'s barracks, the big building on the east side of town (not the inn), a few steps from {npc:3172}, the warlock trainer. {npc:5875} stands with the senior warlocks in the {object:172960}, the cavern under {zone:1454}'s {object:172982}. An Orc or Troll leveling in {zone:1420} can take the {zone:1458} version from {npc:5724} in {area:159} instead (the {zone:1458} steps below): you can do only one of the two."] = "At 10 Ophek sends you to Gan'rul Bloodeye. He stands outside at the back of Razor Hill's barracks, the big building on the east side of town (not the inn), a few steps from Dhugru Gorelust, the warlock trainer. Gan'rul stands with the senior warlocks in the Cleft of Shadow, the cavern under Orgrimmar's Valley of Strength. An Orc or Troll leveling in Tirisfal Glades can take the Undercity version from Ageron Kargal in Brill instead (the Undercity steps below): you can do only one of the two.", ["At 10 {npc:5724}, upstairs in the {area:2119} in {area:159}, sends you to {npc:5675}: the version for the Undead, and for Orcs and Trolls who level in {zone:1420} instead of taking {npc:5875}'s. {npc:5675} stands in the {zone:1458}'s {object:36082}, by the Temple of the Damned."] = "At 10 Ageron Kargal, upstairs in the Gallows' End Tavern in Brill, sends you to Carendin Halgar: the version for the Undead, and for Orcs and Trolls who level in Tirisfal Glades instead of taking Gan'rul's. Carendin stands in the Undercity's Magic Quarter, by the Temple of the Damned.", ["Back to {npc:5675}. He hands you the {item:6284}: go down the stairs from him to the summoning circle and use them while standing on it. Fight the voidwalker (level 10, not elite) on the circle: if it wanders off, the city guards may kill it and the kill does not count. {spell:14868}, Corruption and {spell:348} with your imp tanking bring it down; it hits harder below 30%. If you lose, use the runes again. Keep the runes: {npc:5675} takes them back."] = "Back to Carendin. He hands you the Runes of Summoning: go down the stairs from him to the summoning circle and use them while standing on it. Fight the voidwalker (level 10, not elite) on the circle: if it wanders off, the city guards may kill it and the kill does not count. Curse of Agony, Corruption and Immolate with your imp tanking bring it down; it hits harder below 30%. If you lose, use the runes again. Keep the runes: Carendin takes them back.", ["Back to {npc:5875}. He hands you the {item:7464}: take them across the {object:172960} to {npc:3216}'s tent, stand on the purple circle on its floor and use them. The voidwalker (level 10, not elite) hits hard at 30% health and leaves after three minutes, so start at once: {spell:14868}, Corruption and {spell:348}, send your imp in, and Fear it when you need a breather. If it beats you or leaves, the glyphs are not used up: use them again on the circle. Keep the glyphs: {npc:5875} takes them back."] = "Back to Gan'rul. He hands you the Glyphs of Summoning: take them across the Cleft of Shadow to Neeru Fireblade's tent, stand on the purple circle on its floor and use them. The voidwalker (level 10, not elite) hits hard at 30% health and leaves after three minutes, so start at once: Curse of Agony, Corruption and Immolate, send your imp in, and Fear it when you need a breather. If it beats you or leaves, the glyphs are not used up: use them again on the circle. Keep the glyphs: Gan'rul takes them back.", ["{item:6284}, on the circle below {npc:5675}"] = "Runes of Summoning, on the circle below Carendin" },
			steps = {
				{
					title = "{quest:1506} (Orcs and Trolls)",
					note = "At 10 {npc:3294} sends you to {npc:5875}. He stands outside at the back of {area:362}'s barracks, the big building on the east side of town (not the inn), a few steps from {npc:3172}, the warlock trainer. {npc:5875} stands with the senior warlocks in the {object:172960}, the cavern under {zone:1454}'s {object:172982}. An Orc or Troll leveling in {zone:1420} can take the {zone:1458} version from {npc:5724} in {area:159} instead (the {zone:1458} steps below): you can do only one of the two.",
					only = { races = { "Orc", "Troll" } },
					goals = {
						{ t = "level", level = 10 },
						{ t = "accept", quest = 1506, title = "Gan'rul's Summons", npc = 3294, npcName = "Ophek", minLevel = 10, qlvl = 10, closedBy = { 1501, 1478 }, preTitles = { [1478] = "Halgar's Summons", [1501] = "Creature of the Void" }, map = 1411, x = 54.37, y = 41.29, z = 10.9, f = "e" },
						{ t = "turnin", quest = 1506, title = "Gan'rul's Summons", npc = 5875, npcName = "Gan'rul Bloodeye", map = 1454, x = 48.25, y = 45.28, z = -14.8, f = "e", note = "{npc:5875}, {object:172960}" },
						{ t = "accept", quest = 1501, title = "Creature of the Void", npc = 5875, npcName = "Gan'rul Bloodeye", minLevel = 10, qlvl = 11, closedBy = { 1473 }, preTitles = { [1473] = "Creature of the Void" }, map = 1454, x = 48.25, y = 45.28, z = -14.8, f = "e" },
					},
				},
				{
					title = "{area:817}",
					note = "{area:817} is the cave in the cliffs just east of {zone:1454}'s gate. Inside, take the right-hand ramp up and follow it to the top: the {object:58595} sits on that upper ledge, which cannot be reached from the lower floor. The cave is packed with Burning Blade Apprentices and Fanatics (level 9-11, many with voidwalkers) that respawn quickly, and {npc:3204}, a level 14 Burning Blade warlock, stands near the stash. Old notes call him elite; Forever's data lists him as normal. At 10 it is hard alone: pull one pack at a time and Fear the extra, wait for 11, or go with a friend. The stash always holds the tablet.",
					only = { races = { "Orc", "Troll" } },
					goals = {
						{ t = "collect", quest = 1501, title = "Creature of the Void", item = 6535, itemName = "Tablet of Verga", count = 1, oi = 1, map = 1411, x = 51.62, y = 9.76, f = "e", note = "{item:6535}, in the {object:58595}", from = "Burning Blade Stash", fromKind = "object", fromId = 58595 },
					},
				},
				{
					title = "{quest:1504} ({zone:1454})",
					note = "Back to {npc:5875}. He hands you the {item:7464}: take them across the {object:172960} to {npc:3216}'s tent, stand on the purple circle on its floor and use them. The voidwalker (level 10, not elite) hits hard at 30% health and leaves after three minutes, so start at once: {spell:14868}, Corruption and {spell:348}, send your imp in, and Fear it when you need a breather. If it beats you or leaves, the glyphs are not used up: use them again on the circle. Keep the glyphs: {npc:5875} takes them back.",
					only = { races = { "Orc", "Troll" } },
					goals = {
						{ t = "turnin", quest = 1501, title = "Creature of the Void", npc = 5875, npcName = "Gan'rul Bloodeye", map = 1454, x = 48.25, y = 45.28, z = -14.8, f = "e" },
						{ t = "accept", quest = 1504, title = "The Binding", npc = 5875, npcName = "Gan'rul Bloodeye", minLevel = 10, qlvl = 11, pre = { 1501 }, preTitles = { [1501] = "Creature of the Void" }, map = 1454, x = 48.25, y = 45.28, z = -14.8, f = "e" },
						{ t = "use", item = 7464, itemName = "Glyphs of Summoning", map = 1454, x = 49.4, y = 50, f = "e", note = "{item:7464}, on the circle in Neeru's tent" },
						{ t = "kill", quest = 1504, title = "The Binding", target = "Summoned Voidwalker", npc = 5676, count = 1, oi = 1, map = 1454, x = 49.3, y = 50, f = "e" },
						{ t = "turnin", quest = 1504, title = "The Binding", npc = 5875, npcName = "Gan'rul Bloodeye", map = 1454, x = 48.25, y = 45.28, z = -14.8, f = "e", note = "{npc:5875}: {spell:697}" },
					},
				},
				{
					title = "{quest:1478} ({zone:1458})",
					note = "At 10 {npc:5724}, upstairs in the {area:2119} in {area:159}, sends you to {npc:5675}: the version for the Undead, and for Orcs and Trolls who level in {zone:1420} instead of taking {npc:5875}'s. {npc:5675} stands in the {zone:1458}'s {object:36082}, by the Temple of the Damned.",
					only = { races = { "Orc", "Troll", "Scourge" } },
					goals = {
						{ t = "level", level = 10 },
						{ t = "accept", quest = 1478, title = "Halgar's Summons", npc = 5724, npcName = "Ageron Kargal", minLevel = 10, qlvl = 10, closedBy = { 1473, 1506 }, preTitles = { [1473] = "Creature of the Void", [1506] = "Gan'rul's Summons" }, map = 1420, x = 61.62, y = 52.68, z = 41.2, f = "e", note = "{npc:5724}, upstairs in the {area:159} inn" },
						{ t = "turnin", quest = 1478, title = "Halgar's Summons", npc = 5675, npcName = "Carendin Halgar", map = 1458, x = 85.06, y = 25.99, z = -62.2, f = "e", note = "{npc:5675}, {object:36082}" },
						{ t = "accept", quest = 1473, title = "Creature of the Void", npc = 5675, npcName = "Carendin Halgar", minLevel = 10, qlvl = 10, closedBy = { 1501 }, preTitles = { [1501] = "Creature of the Void" }, map = 1458, x = 85.06, y = 25.99, z = -62.2, f = "e" },
					},
				},
				{
					title = "{object:37098}",
					note = "The Scarlet tower stands in the fields west of the {zone:1458}'s ruins (not the tower near {area:154}). The grimoire is in the small chest on the ground floor, under the stairs; ignore the chest upstairs. {npc:1662} (level 9) and a {npc:1537} guard it: kill them, or Fear the zealot while you deal with Perrine. Scarlet Missionaries and Zealots (level 7-9) walk the fields around the tower. The chest is back three seconds after anyone opens it.",
					only = { races = { "Orc", "Troll", "Scourge" } },
					goals = {
						{ t = "collect", quest = 1473, title = "Creature of the Void", item = 6285, itemName = "Egalin's Grimoire", count = 1, oi = 1, map = 1420, x = 51.06, y = 67.57, f = "e", note = "{item:6285}, in {object:37098}", from = "Perrine's Chest", fromKind = "object", fromId = 37098 },
					},
				},
				{
					title = "{quest:1471} ({zone:1458})",
					note = "Back to {npc:5675}. He hands you the {item:6284}: go down the stairs from him to the summoning circle and use them while standing on it. Fight the voidwalker (level 10, not elite) on the circle: if it wanders off, the city guards may kill it and the kill does not count. {spell:14868}, Corruption and {spell:348} with your imp tanking bring it down; it hits harder below 30%. If you lose, use the runes again. Keep the runes: {npc:5675} takes them back.",
					only = { races = { "Orc", "Troll", "Scourge" } },
					goals = {
						{ t = "turnin", quest = 1473, title = "Creature of the Void", npc = 5675, npcName = "Carendin Halgar", map = 1458, x = 85.06, y = 25.99, z = -62.2, f = "e" },
						{ t = "accept", quest = 1471, title = "The Binding", npc = 5675, npcName = "Carendin Halgar", minLevel = 10, qlvl = 10, pre = { 1473 }, preTitles = { [1473] = "Creature of the Void" }, map = 1458, x = 85.06, y = 25.99, z = -62.2, f = "e" },
						{ t = "use", item = 6284, itemName = "Runes of Summoning", map = 1458, x = 86.6, y = 27.1, f = "e", note = "{item:6284}, on the circle below {npc:5675}" },
						{ t = "kill", quest = 1471, title = "The Binding", target = "Summoned Voidwalker", npc = 5676, count = 1, oi = 1, map = 1458, x = 86.6, y = 27.1, z = -63.8, f = "e" },
						{ t = "turnin", quest = 1471, title = "The Binding", npc = 5675, npcName = "Carendin Halgar", map = 1458, x = 85.06, y = 25.99, z = -62.2, f = "e", note = "{npc:5675}: {spell:697}" },
