			written = { ["East along the road from {area:2539} to {npc:4049}'s camp, on the way to {area:378}."] = "East along the road from Malaka'jin to Seereth's camp, on the way to Camp Taurajo.", ["Follow the road west past Regthar's bunkers and {npc:4049}'s camp into Stonetalon: {npc:3995} waits below ground in {area:2539}, at the foot of the {area:1076}."] = "Follow the road west past Regthar's bunkers and Seereth's camp into Stonetalon: Witch Doctor Jin'Zil waits below ground in Malaka'jin, at the foot of the Webwinder Path.", ["From {area:2539} follow the road east to {npc:4049}'s camp, then south-east across the plains to {area:378}."] = "From Malaka'jin follow the road east to Seereth's camp, then south-east across the plains to Camp Taurajo.", ["On the way back east to {npc:3341}: Hecklefang Stalkers and {npc:3238} lizards roam the plain between the ridge and his camp."] = "On the way back east to Gann: Hecklefang Stalkers and Stormhide lizards roam the plain between the ridge and his camp.", ["South-west of Sun Rock lies the burned {area:465}. Plant the Gaea Seeds in the dirt mounds on the valley floor; the fire elementals drop {item:16312}. Bloodfury Harpies and Ambushers nest on the north side, Slayers and Roguefeathers to the south."] = "South-west of Sun Rock lies the burned Charred Vale. Plant the Gaea Seeds in the dirt mounds on the valley floor; the fire elementals drop Incendrites. Bloodfury Harpies and Ambushers nest on the north side, Slayers and Roguefeathers to the south.", ["The dwarves' flying machine sits on its platform inside the dig site. Use the {item:5021} that {npc:3341} gave you on it."] = "The dwarves' flying machine sits on its platform inside the dig site. Use the Explosive Stick of Gann that Gann gave you on it.", ["The road west past {npc:4049}'s camp"] = "The road west past Seereth's camp", ["{area:1718}"] = "The Great Lift", ["{npc:11860}: {npc:12576} is at the {area:1718}, later in this guide"] = "Maggran Earthbinder: Grish is at the Great Lift, later in this guide", ["{npc:14242}, up in the tree just east of {npc:3341}"] = "Sulhasa, up in the tree just east of Gann", ["{npc:3341} walks the road south toward {area:359}, between about 46,75 and 46,81: if he isn't at the arrow, follow the road until you meet him. {npc:14242} sits up in the tree just east of the road at 47.9,77.5."] = "Gann walks the road south toward Bael Modan, between about 46,75 and 46,81: if he isn't at the arrow, follow the road until you meet him. Sulhasa sits up in the tree just east of the road at 47.9,77.5.", ["{npc:4198}'s next quest, Ordanus, is on the Alliance side of {zone:1440}. Skip it."] = "Braelyn's next quest, Ordanus, is on the Alliance side of Ashenvale. Skip it.", ["{quest:873}, a big threshadon, swims in the shallows off the {area:391}, east of {npc:3388}."] = "Isha Awak, a big threshadon, swims in the shallows off the Merchant Coast, east of Mahren." },
