-- Source: forever/horde/40-50/05-the-hinterlands.guide
do
	local function register()
		Polestar.RegisterGuide({
			id = "forever/horde/40-50/05-the-hinterlands",
			pack = "guides",
			title = "{zone:1425} & {zone:1419}",
			faction = "Horde",
			minLevel = 48,
			maxLevel = 50,
			category = "Leveling",
			zone = 1425,
			zoneName = "The Hinterlands",
			next = "forever/horde/40-50/06-azshara",
			author = "Polestar",
			version = 1,
			names = { ["area:1440"] = "Serpent's Coil", ["area:1446"] = "Thorium Point", ["area:1883"] = "Valorwind Lake", ["area:1884"] = "Agol'watha", ["area:1917"] = "Shaol'watha", ["area:2100"] = "Maraudon", ["area:272"] = "Tarren Mill", ["area:307"] = "The Overlook Cliffs", ["area:3317"] = "Revantusk Village", ["area:348"] = "Aerie Peak", ["area:35"] = "Booty Bay", ["area:350"] = "Quel'Danil Lodge", ["area:351"] = "Skulk Rock", ["area:353"] = "Shadra'Alor", ["area:354"] = "Jintha'Alor", ["area:355"] = "The Altar of Zul", ["area:75"] = "Stonard", ["item:15002"] = "Nimboya's Pike", ["item:4589"] = "Long Elegant Feather", ["item:8526"] = "Violet Tragan", ["item:8684"] = "Hinterlands Honey Ripple", ["item:8704"] = "OOX-09/HL Distress Beacon", ["item:9320"] = "Witherbark Skull", ["item:9594"] = "Wildkin Muisek", ["item:9618"] = "Wildkin Muisek Vessel", ["npc:1443"] = "Fel'zerul", ["npc:14731"] = "Lard", ["npc:14736"] = "Primal Torntusk", ["npc:14738"] = "Otho Moji'ko", ["npc:14748"] = "Vilebranch Kidnapper", ["npc:14757"] = "Elder Torntusk", ["npc:2491"] = "Whiskey Slim", ["npc:2505"] = "Saltwater Snapjaw", ["npc:2659"] = "Razorbeak Skylord", ["npc:2925"] = "Silvermane Howler", ["npc:2926"] = "Silvermane Stalker", ["npc:2929"] = "Savage Owlbeast", ["npc:5982"] = "Black Slayer", ["npc:5984"] = "Starving Snickerfang", ["npc:5988"] = "Scorpok Stinger", ["npc:6986"] = "Dran Droffers", ["npc:7572"] = "Fallen Hero of the Horde", ["npc:7623"] = "Dispatch Commander Ruag", ["npc:7643"] = "Bengor", ["npc:7780"] = "Rin'ji", ["npc:7801"] = "Gilveradin Sunchaser", ["npc:7825"] = "Oran Snakewrithe", ["npc:7977"] = "Gammerita", ["npc:8301"] = "Clack the Reaver", ["npc:8636"] = "Morta'gya the Keeper", ["npc:950"] = "Swamp Talker", ["object:2068"] = "Pupellyverbos Port", ["quest:1429"] = "The Atal'ai Exile", ["quest:2782"] = "Rin'ji's Secret", ["quest:2784"] = "Fall From Grace", ["quest:2932"] = "Grim Message", ["quest:2933"] = "Venom Bottles", ["quest:626"] = "Cortello's Riddle", ["quest:7816"] = "Gammerita, Mon!", ["quest:7845"] = "Kidnapped Elder Torntusk!", ["quest:7849"] = "Separation Anxiety", ["quest:7850"] = "Dark Vessels", ["spell:5416"] = "Venom Sting", ["spell:7367"] = "Infected Bite", ["zone:1419"] = "Blasted Lands", ["zone:1425"] = "The Hinterlands", ["zone:1454"] = "Orgrimmar", ["zone:1458"] = "Undercity" },
			written = { ["Follow the roads east across the {zone:1425} to the troll village on the eastern coast."] = "Follow the roads east across the Hinterlands to the troll village on the eastern coast.", ["His next request, going on to the {area:355}, is for a group."] = "His next request, going on to the Altar of Zul, is for a group.", ["Only with the distress beacon: the robot sits at the head of the river west of {area:351}. Escort it east to the shore beyond the {area:307}; its reward waits with Oglethorpe in {area:35}.\nCareful: Two ambushes spawn during the escort: first three wildkin owlbeasts, then three trolls. Before each, the robot halts and announces it senses danger. Oozes, stealthed wolves and a large turtle along the path can join fights, and they respawn even if cleared beforehand."] = "Only with the distress beacon: the robot sits at the head of the river west of Skulk Rock. Escort it east to the shore beyond the Overlook Cliffs; its reward waits with Oglethorpe in Booty Bay.\nCareful: Two ambushes spawn during the escort: first three wildkin owlbeasts, then three trolls. Before each, the robot halts and announces it senses danger. Oozes, stealthed wolves and a large turtle along the path can join fights, and they respawn even if cleared beforehand.", ["Ride north-east from {area:272} into the {zone:1425} and east along the road; {npc:7801} camps on the hill south of the elves' {area:350}."] = "Ride north-east from Tarren Mill into the Hinterlands and east along the road; Gilveradin Sunchaser camps on the hill south of the elves' Quel'Danil Lodge.", ["South-west of the lake, the Vilebranch soothsayers hold the {area:355}, the troll temple south of the central hills. Qiaga and {npc:8636} (elite, 50) stand at its top: take the soothsayers on the lower steps.\nSouth-west, the Silvermane Howlers roam the hills east of the Witherbark villages."] = "South-west of the lake, the Vilebranch soothsayers hold the Altar of Zul, the troll temple south of the central hills. Qiaga and Morta'gya the Keeper (elite, 50) stand at its top: take the soothsayers on the lower steps.\nSouth-west, the Silvermane Howlers roam the hills east of the Witherbark villages.", ["The big turtles crawl along the beaches north of the village, and {npc:2491}'s bottles of port lie on the same beaches, from the village up to the {area:307}: pick them up as you go. A snapjaw can drop OOX-09/HL's distress beacon, rarely: keep it."] = "The big turtles crawl along the beaches north of the village, and Whiskey Slim's bottles of port lie on the same beaches, from the village up to the Overlook Cliffs: pick them up as you go. A snapjaw can drop OOX-09/HL's distress beacon, rarely: keep it.", ["The secret lies on the {area:307}, above the beach."] = "The secret lies on the Overlook Cliffs, above the beach.", ["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:7977} is a level 48 elite: most classes solo it at level 50, but you may need help. Skip it if you are alone: the route has you grind the XP back.\n{npc:7977} walks the shore below the {area:307}, from the arrow south to about 75,66 and north to about 82,52: if she isn't at the arrow, follow the shore."] = "These are elite mobs: grouping up is encouraged, look for people to do it with. Gammerita is a level 48 elite: most classes solo it at level 50, but you may need help. Skip it if you are alone: the route has you grind the XP back.\nGammerita walks the shore below the Overlook Cliffs, from the arrow south to about 75,66 and north to about 82,52: if she isn't at the arrow, follow the shore.", ["West of the island, the Vilebranch scalpers hold the temples of {area:1884} and {area:1917}. Slagtree's tools lie at one of the temples.\nThe Silvermane Stalkers, Savage Owlbeasts and Razorbeak Skylords share the hills between the temples and {area:351}. Use the {item:9618} on the owlbeasts you kill. The Skylords also drop Long Elegant Feathers: keep ten for {npc:14738}'s second message.\nCareful: Silvermane Stalkers are level 47-48 and stay stealthed while out of combat. Up close they use {spell:7367}. When a {npc:2925} falls to 50% health or lower, it calls for help from anything within 25 yd."] = "West of the island, the Vilebranch scalpers hold the temples of Agol'watha and Shaol'watha. Slagtree's tools lie at one of the temples.\nThe Silvermane Stalkers, Savage Owlbeasts and Razorbeak Skylords share the hills between the temples and Skulk Rock. Use the Wildkin Muisek Vessel on the owlbeasts you kill. The Skylords also drop Long Elegant Feathers: keep ten for Otho's second message.\nCareful: Silvermane Stalkers are level 47-48 and stay stealthed while out of combat. Up close they use Infected Bite. When a Silvermane Howler falls to 50% health or lower, it calls for help from anything within 25 yd.", ["{npc:7801}'s camp"] = "Gilveradin's camp" },
			steps = {
				{
					title = "Fly to {area:272}",
					goals = {
						{ t = "goto", text = "{area:1446} flight master", map = 1427, x = 34.8, y = 30.6, f = "e" },
						{ t = "fly", location = "Tarren Mill", node = 13, area = 272 },
					},
				},
				{
