			written = { ["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5930} sits in the north-western woods. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Cast Teleport: Moonglade. Dendrite Starblaze is in Nighthaven; the Great Bear Spirit sits in the north-western woods. Dendrite stands upstairs in his building: go up inside, the arrow cannot tell the floors apart.", ["Leave {zone:1412} by the south-eastern pass and follow the road to the Crossroads. {npc:3448} stands at the south gate, {quest:860} by the inn, {npc:3615} on the tower platform. {area:380}' own quests come after {zone:1421}, in the {zone:1413} guide."] = "Leave Mulgore by the south-eastern pass and follow the road to the Crossroads. Tonga Runetotem stands at the south gate, Sergra Darkthorn by the inn, Devrak on the tower platform. The Crossroads' own quests come after Silverpine Forest, in the Barrens guide.", ["Plainstriders roam the mesa all around the camp: take their meat and feathers on the way back to {npc:2980}."] = "Plainstriders roam the mesa all around the camp: take their meat and feathers on the way back to Grull.", ["Prairie Wolf Alphas roam among the wolves on the plains around {npc:275789} and the Galak camp to the east."] = "Prairie Wolf Alphas roam among the wolves on the plains around Malah and the Galak camp to the east.", ["Ride a lift up to the mesas. {npc:2995} keeps the wind riders on the central rise; {npc:3057} stands in the great tent there."] = "Ride a lift up to the mesas. Tal keeps the wind riders on the central rise; Cairne stands in the great tent there.", ["You start on the mesa of {area:221}. {npc:2980} and the chief stand by the big tent in the middle."] = "You start on the mesa of Camp Narache. Grull and the chief stand by the big tent in the middle.", ["{npc:10378}, beside {npc:3418}"] = "Omusa Thunderhorn, beside Kirge", ["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "Eylah Sunhorn wants tauren incense: buy its four parts from Nida the herbalist, Nata the enchanting supplier, Mahu the leatherworking supplier and Naal the cooking supplier, then combine them into Prepared Incense.", ["{npc:277182} stands at the north edge of the village. Kyle wants {item:287505} from plainstriders."] = "Ahab stands at the north edge of the village. Kyle wants Tender Strider Meat from plainstriders.", ["{npc:2987}, beside {npc:269068}"] = "Eyahn Eagletalon, beside Eylah", ["{npc:2993}, for {npc:3057} in {zone:1456}"] = "Baine Bloodhoof, for Cairne in Thunder Bluff", ["{npc:3039}, beside {npc:3041}"] = "Holt Thunderhorn, beside Torm", ["{npc:3057}'s tent"] = "Cairne's tent", ["{npc:3069}, beside {npc:3067}: {quest:97934}"] = "Chaw Stronghide, beside Pyall: Camping 101: Leatherworking", ["{npc:3209}, next to {npc:2980}; walks around {area:221}: look inside the circle on the map"] = "Brave Windfeather, next to Grull; walks around Camp Narache: look inside the circle on the map", ["{npc:3483} sells armor on the north side of the Crossroads. His bundle goes to {npc:3615}, who sends it with you on the flight to {zone:1456} you take for {npc:3033} anyway."] = "Jahan Hawkwing sells armor on the north side of the Crossroads. His bundle goes to Devrak, who sends it with you on the flight to Thunder Bluff you take for Turak anyway.", ["{npc:6290}, beside {npc:3067}: {quest:97936}"] = "Yonn Deepcut, beside Pyall: Camping 101: Skinning", ["{npc:6746}: {quest:5926}, for {npc:3033} on {area:1639}"] = "Innkeeper Pala: Heeding the Call, for Turak on Elder Rise", ["{npc:6775} stands at the west end of the camp, at the north-west corner of the hills where the Mountain Cougars prowl: take his quest, hunt the cougars from there south and east, then come back up to {npc:2980}."] = "Antur Fallow stands at the west end of the camp, at the north-west corner of the hills where the Mountain Cougars prowl: take his quest, hunt the cougars from there south and east, then come back up to Grull." },
